task test_sequential_register_access();
    wb_stb_i = 1'b1;
    wb_cyc_i = 1'b1;

    wb_we_i = 1'b1;

    foreach(all_registers[i]) begin
        wb_sel_i = $urandom;
        wb_dat_i = $urandom;
        wb_adr_i = all_registers[i];
        #(CLK_PERIOD);
    end

    wb_we_i = 1'b0;

    foreach(all_registers[i]) begin
        wb_sel_i = $urandom;
        wb_adr_i = all_registers[i];
        #(CLK_PERIOD);
    end

    wb_stb_i = 1'b0;
    wb_cyc_i = 1'b0;
    #(CLK_PERIOD);
endtask

task test_sd_controller_operations();
    write_req_s = 1'b0;
    cmd_set_s = 16'h0000;
    cmd_arg_s = 32'h00000000;

    repeat(10) begin
        cmd_set_s = $urandom;
        cmd_arg_s = $urandom;

        wb_stb_i = 1'b1;
        wb_cyc_i = 1'b1;
        wb_we_i = 1'b1;
        wb_sel_i = 4'b1111;

        wb_adr_i = `argument;
        wb_dat_i = cmd_arg_s;
        #(CLK_PERIOD);

        wb_adr_i = `command;
        wb_dat_i = {16'h0000, cmd_set_s};
        #(CLK_PERIOD);

        wb_stb_i = 1'b0;
        wb_cyc_i = 1'b0;
        #(CLK_PERIOD * 5);

        write_req_s = 1'b1;
        #(CLK_PERIOD * 2);
        write_req_s = 1'b0;

        status_reg = $urandom;
        normal_int_status_reg = $urandom;
        error_int_status_reg = $urandom;
        cmd_resp_1 = $urandom;
        #(CLK_PERIOD * 3);

        wb_stb_i = 1'b1;
        wb_cyc_i = 1'b1;
        wb_we_i = 1'b0;

        wb_adr_i = `status;
        #(CLK_PERIOD);

        wb_adr_i = `resp1;
        #(CLK_PERIOD);

        wb_adr_i = `normal_isr;
        #(CLK_PERIOD);

        wb_adr_i = `error_isr;
        #(CLK_PERIOD);

        wb_stb_i = 1'b0;
        wb_cyc_i = 1'b0;
        #(CLK_PERIOD * 2);
    end
endtask

task test_boundary_conditions();
    wb_stb_i = 1'b1;
    wb_cyc_i = 1'b1;
    wb_we_i = 1'b1;
    wb_dat_i = $urandom;
    wb_adr_i = `argument;
    #(CLK_PERIOD/2);

    wb_cyc_i = 1'b0;
    #(CLK_PERIOD/2);
    wb_stb_i = 1'b0;
    #(CLK_PERIOD);

    wb_stb_i = 1'b1;
    wb_cyc_i = 1'b1;
    wb_adr_i = 8'hFF;
    #(CLK_PERIOD * 2);

    wb_adr_i = `argument;
    repeat(16) begin
        wb_sel_i = $urandom;
        wb_dat_i = $urandom;
        #(CLK_PERIOD);
    end

    wb_stb_i = 1'b0;
    wb_cyc_i = 1'b0;
    #(CLK_PERIOD);
endtask

task test_random_stimulus(int iterations);
    repeat(iterations) begin
        wb_rst_i = ($urandom % 20 == 0);
        wb_stb_i = $random;
        wb_cyc_i = $random;
        wb_we_i = $random;
        wb_sel_i = $urandom;
        wb_dat_i = $urandom;
        wb_adr_i = all_registers[$urandom % $size(all_registers)];

        write_req_s = $random;
        cmd_set_s = $urandom;
        cmd_arg_s = $urandom;

        if ($urandom % 10 == 0) begin
            status_reg = $urandom;
            cmd_resp_1 = $urandom;
            normal_int_status_reg = $urandom;
            error_int_status_reg = $urandom;
            Bd_Status_reg = $urandom;
            Bd_isr_reg = $urandom;
        end

        #(CLK_PERIOD);
    end
endtask

// Stimulus generation
initial begin
    wb_rst_i = 1'b0;
    wb_stb_i = 1'b0;
    wb_cyc_i = 1'b0;
    wb_we_i = 1'b0;
    wb_sel_i = 4'b0000;
    wb_dat_i = 32'h00000000;
    wb_adr_i = 8'h00;
    write_req_s = 1'b0;
    cmd_set_s = 16'h0000;
    cmd_arg_s = 32'h00000000;
    status_reg = 16'h0000;
    cmd_resp_1 = 32'h00000000;
    normal_int_status_reg = 16'h0000;
    error_int_status_reg = 16'h0000;
    Bd_Status_reg = 16'h0000;
    Bd_isr_reg = 8'h00;

    // reset
    wb_rst_i = 1'b1;
    #(CLK_PERIOD *3);
    wb_rst_i = 1'b0;
    #(CLK_PERIOD * 3);

    // select this slave
    wb_stb_i = 1'b1;
    wb_cyc_i = 1'b1;
    wb_sel_i = 4'b1111; 

    wb_we_i = 1'b1;
    wb_dat_i = $urandom;
    wb_adr_i = `argument;
    #(CLK_PERIOD);
    wb_adr_i = `command;
    #(CLK_PERIOD);
    wb_adr_i = `software;
    #(CLK_PERIOD);

    #(CLK_PERIOD * 5);

    test_reset();
    #(CLK_PERIOD * 5);

    test_sequential_register_access();
    #(CLK_PERIOD * 5);

    test_sd_controller_operations();
    #(CLK_PERIOD * 5);

    test_boundary_conditions();
    #(CLK_PERIOD * 5);

    test_random_stimulus(5000);

    #(CLK_PERIOD * 10);
    $finish;
end

