143: always @(*) begin
144:     argument_reg_next                 = argument_reg;
145:     cmd_setting_reg_next              = cmd_setting_reg;
146:     software_reset_reg_next           = software_reset_reg;
147:     time_out_reg_next                 = time_out_reg;
148:     normal_int_signal_enable_reg_next = normal_int_signal_enable_reg;
149:     error_int_signal_enable_reg_next  = error_int_signal_enable_reg;
150:     clock_divider_next                = clock_divider;
151:     Bd_isr_enable_reg_next            = Bd_isr_enable_reg;
