153:     bd_state_next                     = bd_state;
154:     bd_high_word_next                 = bd_high_word;
155: 
156:     wb_dat_o_next                     = wb_dat_o;
157:     wb_ack_o_next                     = 1'b0;
158:     we_m_tx_bd_next                   = 1'b0;
159:     we_m_rx_bd_next                   = 1'b0;
160:     new_cmd_next                      = 1'b0;
161:     we_ack_next                       = 1'b0;
162:     int_ack_next                      = 1'b1;
163:     cmd_int_busy_next                 = 1'b0;
164:     int_busy_next                     = int_busy;
165:     Bd_isr_reset_next                 = 1'b0;
166:     normal_isr_reset_next             = 1'b0;
167:     error_isr_reset_next              = 1'b0;
