171:     if (wb_access) begin
172:         if (addr_argument) begin
173:             wb_dat_o_next = argument_reg;
174:         end else if (addr_cmd_setting) begin
175:             wb_dat_o_next = {16'h0000, cmd_setting_reg};
176:         end else if (addr_card_status) begin
177:             wb_dat_o_next = {16'h0000, status_reg};
178:         end else if (addr_response) begin
179:             wb_dat_o_next = cmd_resp_1;
180:         end else if (addr_controller_setting) begin
181:             wb_dat_o_next = {16'h0000, CONTROLLER_SETTING_RESET};
182:         end else if (addr_block_size) begin
183:             wb_dat_o_next = {16'h0000, BLOCK_SIZE_RESET};
184:         end else if (addr_power_control) begin
