186:         end else if (addr_software_reset) begin
187:             wb_dat_o_next = {24'h000000, software_reset_reg};
188:         end else if (addr_timeout) begin
189:             wb_dat_o_next = {16'h0000, time_out_reg};
190:         end else if (addr_normal_int_status) begin
191:             wb_dat_o_next = {16'h0000, normal_int_status_reg[15:0]};
192:         end else if (addr_error_int_status) begin
193:             wb_dat_o_next = {16'h0000, error_int_status_reg[15:0]};
194:         end else if (addr_normal_int_enable) begin
195:             wb_dat_o_next = {16'h0000, normal_int_signal_enable_reg};
196:         end else if (addr_error_int_enable) begin
197:             wb_dat_o_next = {16'h0000, error_int_signal_enable_reg};
198:         end else if (addr_capability) begin
199:             wb_dat_o_next = {16'h0000, CAPABILITY_REG_RESET};
200:         end else if (addr_clock_divider) begin
201:             wb_dat_o_next = {24'h000000, clock_divider};
202:         end else if (addr_bd_status) begin
203:             wb_dat_o_next = {16'h0000, Bd_Status_reg[15:0]};
204:         end else if (addr_bd_isr_status) begin
205:             wb_dat_o_next = {24'h000000, Bd_isr_reg};
206:         end else if (addr_bd_isr_enable) begin
207:             wb_dat_o_next = {24'h000000, Bd_isr_enable_reg};
208:         end
209:     end
210: 
211:     if (write_req_s && !(wb_access || wb_ack_o)) begin
212:         argument_reg_next    = cmd_arg_s;
213:         cmd_setting_reg_next = cmd_set_s;
214:         new_cmd_next         = 1'b1;
215:         we_ack_next          = 1'b1;
216:         cmd_int_busy_next    = 1'b1;
217:     end
218: 
219:     if (((wb_access || wb_ack_o) && wb_we_i) && int_ack) begin
220:         if (addr_argument) begin
221:             argument_reg_next = wb_dat_i;
222:             new_cmd_next      = 1'b1;
223:         end else if (addr_cmd_setting) begin
224:             cmd_setting_reg_next = wb_dat_i[15:0];
225:             int_busy_next        = 1'b1;
226:         end else if (addr_software_reset) begin
227:             if (wb_sel_i[0]) begin
228:                 software_reset_reg_next = wb_dat_i[7:0];
229:             end
230:         end else if (addr_timeout) begin
231:             time_out_reg_next = wb_dat_i[15:0];
232:         end else if (addr_normal_int_status) begin
233:             normal_isr_reset_next = 1'b1;
234:         end else if (addr_error_int_status) begin
235:             error_isr_reset_next = 1'b1;
236:         end else if (addr_normal_int_enable) begin
237:             normal_int_signal_enable_reg_next = wb_dat_i[15:0];
238:         end else if (addr_error_int_enable) begin
239:             error_int_signal_enable_reg_next = wb_dat_i[15:0];
240:         end else if (addr_clock_divider) begin
241:             clock_divider_next = wb_dat_i[7:0];
242:         end else if (addr_bd_isr_status) begin
243:             Bd_isr_reset_next = 1'b1;
244:         end else if (addr_bd_isr_enable) begin
245:             if (wb_sel_i[0]) begin
