247:             end
248:         end
249:     end
250: 
251:     if (wb_write_access && (addr_bd_rx || addr_bd_tx)) begin
252:         bd_state_next = bd_state + 2'b01;
253:         int_ack_next  = 1'b0;
254: 
255:         if (bd_state == BD_IDLE) begin
