260:             end else begin
261:                 we_m_tx_bd_next = 1'b0;
262:             end
263:         end else if (bd_state == BD_RX_HIGH) begin
264:             if (addr_bd_rx) begin
265:                 we_m_rx_bd_next     = 1'b1;
266:                 dat_in_m_rx_bd_next = wb_dat_i[15:0];
267:             end else begin
268:                 we_m_tx_bd_next     = 1'b1;
269:                 dat_in_m_tx_bd_next = wb_dat_i[15:0];
270:             end
271:         end else if (bd_state == BD_TX_HIGH) begin
272:             if (addr_bd_rx) begin
273:                 we_m_rx_bd_next     = 1'b1;
274:                 dat_in_m_rx_bd_next = wb_dat_i[31:16];
275:             end else begin
276:                 we_m_tx_bd_next     = 1'b1;
277:                 dat_in_m_tx_bd_next = wb_dat_i[31:16];
278:             end
279:         end else begin
280:             int_ack_next  = 1'b1;
281:             bd_state_next = BD_IDLE;
282:             if (addr_bd_rx) begin
283:                 we_m_rx_bd_next = 1'b0;
284:             end else begin
285:                 we_m_tx_bd_next = 1'b0;
286:             end
287:         end
288:     end
289: 
290:     if (status_reg[0]) begin
291:         int_busy_next = 1'b0;
292:     end
293: 
294:     if (wb_access && !wb_ack_o && int_ack_next) begin
295:         wb_ack_o_next = 1'b1;
296:     end
297: end
